#include <stddef.h>
#include <stdint.h>

/* Implemented in Go and exported through cgo. */
extern int GoIDORFixTarget(unsigned char *data, long long size);

/*
 * libFuzzer entry point. Every generated byte string is forwarded into the Go
 * detection engine. A non-zero return from the Go side aborts the run and
 * writes a reproducer into the corpus directory.
 */
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
	return GoIDORFixTarget((unsigned char *)data, (long long)size);
}
